def cidr_contains(cidr: str, ip: str) -> bool:
    def parse_ip(s):
        parts = s.split('.')
        if len(parts) != 4:
            raise ValueError("bad ip")
        octets = []
        for p in parts:
            if not p or not p.isdigit():
                raise ValueError("bad octet")
            if p[0] == '+' or (len(p) > 1 and p[0] == '0'):
                raise ValueError("bad octet format")
            v = int(p)
            if v < 0 or v > 255:
                raise ValueError("octet out of range")
            octets.append(v)
        return (octets[0] << 24) | (octets[1] << 16) | (octets[2] << 8) | octets[3]

    if '/' not in cidr:
        raise ValueError("missing slash")
    net_str, prefix_str = cidr.split('/', 1)
    if not prefix_str.isdigit() or (len(prefix_str) > 1 and prefix_str[0] == '0'):
        raise ValueError("bad prefix")
    prefix = int(prefix_str)
    if prefix < 0 or prefix > 32:
        raise ValueError("prefix out of range")

    net_ip = parse_ip(net_str)
    target_ip = parse_ip(ip)

    if prefix == 0:
        mask = 0
    else:
        mask = (0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF

    return (net_ip & mask) == (target_ip & mask)
